HII_ADDITION = '#include "AuroraStringDiagnosticProtocol.h"\n\n#define AURORA_HII_STAGE(Number) \\\n  do { if (AuroraTrace != NULL) { AuroraTrace->Stage (Number); } } while (0)\n'

