CANVAS_ORIGINAL = "static\nEFI_STATUS\nSetDefaultControl (\n  IN struct _Canvas  *this,\n  IN VOID            *pControl\n  )\n{\n  EFI_STATUS                Status        = EFI_NOT_FOUND;\n  UIT_CANVAS_CHILD_CONTROL  *pControlList = this->m_pControls;\n  ControlBase               *pControlBase;\n\n  // TODO: Need to check whether there's already a default control?\n\n  // Walk through the list of child controls, looking for the caller-specified control.\n  //\n  while (NULL != pControlList) {\n    // If we found it set it as the default control.\n    //\n    if (pControlList->pControl == pControl) {\n      this->m_pDefaultControl = pControlList;\n      Status                  = EFI_SUCCESS;\n      break;\n    }\n\n    pControlList = pControlList->pNext;\n  }\n\n  if (EFI_ERROR (Status)) {\n    DEBUG ((DEBUG_INFO, \"INFO [SUIT]: Failed to find canvas child control to set as default (%r).\\r\\n\", Status));\n    goto Exit;\n  }\n\n  // Update the control's state so it can signal that it's the default (visual indicator) then draw.\n  //\n  pControlBase = (ControlBase *)this->m_pDefaultControl->pControl;\n\n  pControlBase->SetControlState (\n                  pControlBase,\n                  KEYDEFAULT\n                  );\n\n  pControlBase->Draw (\n                  pControlBase,\n                  FALSE,\n                  NULL,\n                  NULL\n                  );\n\nExit:\n\n  return Status;\n}\n"
CANVAS_REPLACEMENT = "static\nEFI_STATUS\nSetDefaultControl (\n  IN struct _Canvas  *this,\n  IN VOID            *pControl\n  )\n{\n  EFI_STATUS                Status        = EFI_NOT_FOUND;\n  UIT_CANVAS_CHILD_CONTROL  *pControlList = this->m_pControls;\n  ControlBase               *pControlBase;\n\n  AuroraCanvasDiagnosticStage (171);\n\n  // TODO: Need to check whether there's already a default control?\n\n  // Walk through the list of child controls, looking for the caller-specified control.\n  //\n  while (NULL != pControlList) {\n    // If we found it set it as the default control.\n    //\n    if (pControlList->pControl == pControl) {\n      this->m_pDefaultControl = pControlList;\n      Status                  = EFI_SUCCESS;\n      break;\n    }\n\n    pControlList = pControlList->pNext;\n  }\n\n  AuroraCanvasDiagnosticStage (172);\n  if (EFI_ERROR (Status)) {\n    AuroraCanvasDiagnosticStage (173);\n    DEBUG ((DEBUG_INFO, \"INFO [SUIT]: Failed to find canvas child control to set as default (%r).\\r\\n\", Status));\n    goto Exit;\n  }\n\n  // Update the control's state so it can signal that it's the default (visual indicator) then draw.\n  //\n  pControlBase = (ControlBase *)this->m_pDefaultControl->pControl;\n\n  AuroraCanvasDiagnosticStage (174);\n  pControlBase->SetControlState (\n                  pControlBase,\n                  KEYDEFAULT\n                  );\n\n  AuroraCanvasDiagnosticStage (175);\n  AuroraCanvasDiagnosticStage (176);\n  pControlBase->Draw (\n                  pControlBase,\n                  FALSE,\n                  NULL,\n                  NULL\n                  );\n\n  AuroraCanvasDiagnosticStage (177);\n\nExit:\n  AuroraCanvasDiagnosticStage (178);\n\n  return Status;\n}\n"
CANVAS_HELPERS = "// Aurora hooks are NULL except in the diagnostic FrontPage library instance.\ntypedef VOID (*AURORA_CANVAS_DIAGNOSTIC_CALLBACK)(IN UINTN Stage);\ntypedef VOID (*AURORA_CANVAS_DIAGNOSTIC_RESULT_CALLBACK)(IN CONST CHAR8 *Operation, IN EFI_STATUS Status);\nSTATIC AURORA_CANVAS_DIAGNOSTIC_CALLBACK mAuroraCanvasDiagnosticCallback = NULL;\nSTATIC AURORA_CANVAS_DIAGNOSTIC_RESULT_CALLBACK mAuroraCanvasDiagnosticResultCallback = NULL;\n\nVOID\nAuroraCanvasSetDiagnosticCallback (\n  IN AURORA_CANVAS_DIAGNOSTIC_CALLBACK Callback,\n  IN AURORA_CANVAS_DIAGNOSTIC_RESULT_CALLBACK ResultCallback\n  );\n\nVOID\nAuroraCanvasDiagnosticStage (\n  IN UINTN Stage\n  );\n\nVOID\nAuroraCanvasDiagnosticResult (\n  IN CONST CHAR8 *Operation,\n  IN EFI_STATUS Status\n  );\n\nVOID\nAuroraCanvasSetDiagnosticCallback (\n  IN AURORA_CANVAS_DIAGNOSTIC_CALLBACK Callback,\n  IN AURORA_CANVAS_DIAGNOSTIC_RESULT_CALLBACK ResultCallback\n  )\n{\n  mAuroraCanvasDiagnosticCallback = Callback;\n  mAuroraCanvasDiagnosticResultCallback = ResultCallback;\n}\n\nVOID\nAuroraCanvasDiagnosticStage (\n  IN UINTN Stage\n  )\n{\n  if (mAuroraCanvasDiagnosticCallback != NULL) {\n    mAuroraCanvasDiagnosticCallback (Stage);\n  }\n}\n\nVOID\nAuroraCanvasDiagnosticResult (\n  IN CONST CHAR8 *Operation,\n  IN EFI_STATUS Status\n  )\n{\n  if (mAuroraCanvasDiagnosticResultCallback != NULL) {\n    mAuroraCanvasDiagnosticResultCallback (Operation, Status);\n  }\n}\n\n"
BUTTON_RENDER_ORIGINAL = "static\nEFI_STATUS\nRenderButton (\n  IN Button   *this,\n  IN BOOLEAN  DrawHighlight\n  )\n{\n  EFI_STATUS                     Status = EFI_SUCCESS;\n  UINTN                          Width, Height;\n  EFI_FONT_DISPLAY_INFO          *StringInfo = NULL;\n  EFI_IMAGE_OUTPUT               *pBltBuffer = NULL;\n  EFI_GRAPHICS_OUTPUT_BLT_PIXEL  *pTextColor;\n  EFI_GRAPHICS_OUTPUT_BLT_PIXEL  *pFillColor;\n\n  // Color.\n  //\n  switch (this->m_pButton->State) {\n    case KEYDEFAULT:\n    case HOVER:\n    case SELECT:\n      if (this->m_ButtonDown) {\n        pFillColor = &this->m_SelectColor;\n        pTextColor = &this->m_SelectTextColor;\n      } else {\n        pFillColor = &this->m_HoverColor;\n        pTextColor = &this->m_NormalTextColor;\n      }\n\n      break;\n    case GRAYED:\n      pFillColor = &this->m_NormalColor;\n      pTextColor = &this->m_GrayOutTextColor;\n      break;\n    case NORMAL:\n    default:\n      pFillColor = &this->m_NormalColor;\n      pTextColor = &this->m_NormalTextColor;\n      break;\n  }\n\n  StringInfo = BuildFontDisplayInfoFromFontInfo (this->m_FontInfo);\n  if (NULL == StringInfo) {\n    Status = EFI_OUT_OF_RESOURCES;\n    goto Exit;\n  }\n\n  CopyMem (&StringInfo->BackgroundColor, pFillColor, sizeof (EFI_GRAPHICS_OUTPUT_BLT_PIXEL));\n  CopyMem (&StringInfo->ForegroundColor, pTextColor, sizeof (EFI_GRAPHICS_OUTPUT_BLT_PIXEL));\n\n  // Prepare string blitting buffer.\n  //\n  pBltBuffer = (EFI_IMAGE_OUTPUT *)AllocateZeroPool (sizeof (EFI_IMAGE_OUTPUT));\n  ASSERT (pBltBuffer != NULL);\n\n  if (NULL == pBltBuffer) {\n    Status = EFI_OUT_OF_RESOURCES;\n    goto Exit;\n  }\n\n  pBltBuffer->Width        = (UINT16)mUITGop->Mode->Info->HorizontalResolution;\n  pBltBuffer->Height       = (UINT16)mUITGop->Mode->Info->VerticalResolution;\n  pBltBuffer->Image.Screen = mUITGop;\n\n  // Compute button width and height.\n  //\n  Width  = SWM_RECT_WIDTH (this->m_pButton->ButtonBounds);\n  Height = SWM_RECT_HEIGHT (this->m_pButton->ButtonBounds);\n\n  // Draw the button's - outer rectangle first.\n  //\n  DrawRectangleOutline (\n    this->m_pButton->ButtonBounds.Left,\n    this->m_pButton->ButtonBounds.Top,\n    (UINT32)Width,\n    (UINT32)Height,\n    UIT_B_OUTER_BORDER_WIDTH,\n    &this->m_ButtonRingColor\n    );\n\n  // TODO\n  UINTN  ButtonFillOrigX  = this->m_pButton->ButtonBounds.Left + UIT_B_OUTER_BORDER_WIDTH;\n  UINTN  ButtonFillOrigY  = this->m_pButton->ButtonBounds.Top  + UIT_B_OUTER_BORDER_WIDTH;\n  UINTN  ButtonFillWidth  = (Width  - (UIT_B_OUTER_BORDER_WIDTH * 2));\n  UINTN  ButtonFillHeight = (Height - (UIT_B_OUTER_BORDER_WIDTH * 2));\n\n  // Draw the button's - inner rectangle next.\n  //\n  mUITSWM->BltWindow (\n             mUITSWM,\n             mClientImageHandle,\n             pFillColor,\n             EfiBltVideoFill,\n             0,\n             0,\n             ButtonFillOrigX,\n             ButtonFillOrigY,\n             ButtonFillWidth,\n             ButtonFillHeight,\n             ButtonFillWidth * sizeof (EFI_GRAPHICS_OUTPUT_BLT_PIXEL)\n             );\n\n  // Draw the button's - keyboard focus highlight rectangle if it's needed.\n  //\n  if (TRUE == DrawHighlight) {\n    DrawRectangleOutline (\n      (UINT32)ButtonFillOrigX+1,\n      (UINT32)ButtonFillOrigY+1,\n      (UINT32)ButtonFillWidth-2,\n      (UINT32)ButtonFillHeight-2,\n      UIT_B_HIGHLIGHT_RING_WIDTH,\n      &gMsColorTable.ButtonHighlightBoundColor\n      );\n  }\n\n  // Draw button text.\n  //\n  // Select preferred font size and style for the button (smaller, normal font).\n  //\n  StringInfo->FontInfoMask = EFI_FONT_INFO_ANY_FONT;\n\n  mUITSWM->StringToWindow (\n             mUITSWM,\n             mClientImageHandle,\n             EFI_HII_OUT_FLAG_CLIP |\n             EFI_HII_OUT_FLAG_CLIP_CLEAN_X | EFI_HII_OUT_FLAG_CLIP_CLEAN_Y |\n             EFI_HII_IGNORE_LINE_BREAK | EFI_HII_DIRECT_TO_SCREEN,\n             this->m_pButton->pButtonText,\n             StringInfo,\n             &pBltBuffer,\n             this->m_pButton->ButtonTextBounds.Left,\n             this->m_pButton->ButtonTextBounds.Top,\n             NULL,\n             NULL,\n             NULL\n             );\n\nExit:\n\n  if (NULL != StringInfo) {\n    FreePool (StringInfo);\n  }\n\n  if (NULL != pBltBuffer) {\n    FreePool (pBltBuffer);\n  }\n\n  return Status;\n}\n"
BUTTON_RENDER_REPLACEMENT = "static\nEFI_STATUS\nRenderButton (\n  IN Button   *this,\n  IN BOOLEAN  DrawHighlight\n  )\n{\n  EFI_STATUS                     Status = EFI_SUCCESS;\n  EFI_STATUS                     DiagnosticCallStatus;\n  UINTN                          Width, Height;\n  EFI_FONT_DISPLAY_INFO          *StringInfo = NULL;\n  EFI_IMAGE_OUTPUT               *pBltBuffer = NULL;\n  EFI_GRAPHICS_OUTPUT_BLT_PIXEL  *pTextColor;\n  EFI_GRAPHICS_OUTPUT_BLT_PIXEL  *pFillColor;\n\n  AuroraCanvasDiagnosticStage (201);\n\n  // Color.\n  //\n  switch (this->m_pButton->State) {\n    case KEYDEFAULT:\n    case HOVER:\n    case SELECT:\n      if (this->m_ButtonDown) {\n        pFillColor = &this->m_SelectColor;\n        pTextColor = &this->m_SelectTextColor;\n      } else {\n        pFillColor = &this->m_HoverColor;\n        pTextColor = &this->m_NormalTextColor;\n      }\n\n      break;\n    case GRAYED:\n      pFillColor = &this->m_NormalColor;\n      pTextColor = &this->m_GrayOutTextColor;\n      break;\n    case NORMAL:\n    default:\n      pFillColor = &this->m_NormalColor;\n      pTextColor = &this->m_NormalTextColor;\n      break;\n  }\n\n  AuroraCanvasDiagnosticStage (202);\n  StringInfo = BuildFontDisplayInfoFromFontInfo (this->m_FontInfo);\n  AuroraCanvasDiagnosticStage (203);\n  if (NULL == StringInfo) {\n    Status = EFI_OUT_OF_RESOURCES;\n    goto Exit;\n  }\n\n  CopyMem (&StringInfo->BackgroundColor, pFillColor, sizeof (EFI_GRAPHICS_OUTPUT_BLT_PIXEL));\n  CopyMem (&StringInfo->ForegroundColor, pTextColor, sizeof (EFI_GRAPHICS_OUTPUT_BLT_PIXEL));\n\n  // Prepare string blitting buffer.\n  //\n  AuroraCanvasDiagnosticStage (204);\n  pBltBuffer = (EFI_IMAGE_OUTPUT *)AllocateZeroPool (sizeof (EFI_IMAGE_OUTPUT));\n  AuroraCanvasDiagnosticStage (205);\n  ASSERT (pBltBuffer != NULL);\n\n  if (NULL == pBltBuffer) {\n    Status = EFI_OUT_OF_RESOURCES;\n    goto Exit;\n  }\n\n  AuroraCanvasDiagnosticStage (206);\n  pBltBuffer->Width        = (UINT16)mUITGop->Mode->Info->HorizontalResolution;\n  pBltBuffer->Height       = (UINT16)mUITGop->Mode->Info->VerticalResolution;\n  pBltBuffer->Image.Screen = mUITGop;\n\n  // Compute button width and height.\n  //\n  Width  = SWM_RECT_WIDTH (this->m_pButton->ButtonBounds);\n  Height = SWM_RECT_HEIGHT (this->m_pButton->ButtonBounds);\n\n  AuroraCanvasDiagnosticStage (207);\n\n  // Draw the button's - outer rectangle first.\n  //\n  AuroraCanvasDiagnosticStage (208);\n  DrawRectangleOutline (\n    this->m_pButton->ButtonBounds.Left,\n    this->m_pButton->ButtonBounds.Top,\n    (UINT32)Width,\n    (UINT32)Height,\n    UIT_B_OUTER_BORDER_WIDTH,\n    &this->m_ButtonRingColor\n    );\n\n  AuroraCanvasDiagnosticStage (209);\n\n  // TODO\n  UINTN  ButtonFillOrigX  = this->m_pButton->ButtonBounds.Left + UIT_B_OUTER_BORDER_WIDTH;\n  UINTN  ButtonFillOrigY  = this->m_pButton->ButtonBounds.Top  + UIT_B_OUTER_BORDER_WIDTH;\n  UINTN  ButtonFillWidth  = (Width  - (UIT_B_OUTER_BORDER_WIDTH * 2));\n  UINTN  ButtonFillHeight = (Height - (UIT_B_OUTER_BORDER_WIDTH * 2));\n\n  // Draw the button's - inner rectangle next.\n  //\n  AuroraCanvasDiagnosticStage (210);\n  DiagnosticCallStatus = mUITSWM->BltWindow (\n             mUITSWM,\n             mClientImageHandle,\n             pFillColor,\n             EfiBltVideoFill,\n             0,\n             0,\n             ButtonFillOrigX,\n             ButtonFillOrigY,\n             ButtonFillWidth,\n             ButtonFillHeight,\n             ButtonFillWidth * sizeof (EFI_GRAPHICS_OUTPUT_BLT_PIXEL)\n             );\n\n  AuroraCanvasDiagnosticResult (\"BUTTON FILL\", DiagnosticCallStatus);\n  AuroraCanvasDiagnosticStage (211);\n\n  // Draw the button's - keyboard focus highlight rectangle if it's needed.\n  //\n  AuroraCanvasDiagnosticStage (212);\n  if (TRUE == DrawHighlight) {\n    DrawRectangleOutline (\n      (UINT32)ButtonFillOrigX+1,\n      (UINT32)ButtonFillOrigY+1,\n      (UINT32)ButtonFillWidth-2,\n      (UINT32)ButtonFillHeight-2,\n      UIT_B_HIGHLIGHT_RING_WIDTH,\n      &gMsColorTable.ButtonHighlightBoundColor\n      );\n  }\n\n  AuroraCanvasDiagnosticStage (213);\n\n  // Draw button text.\n  //\n  // Select preferred font size and style for the button (smaller, normal font).\n  //\n  StringInfo->FontInfoMask = EFI_FONT_INFO_ANY_FONT;\n\n  AuroraCanvasDiagnosticStage (214);\n  DiagnosticCallStatus = mUITSWM->StringToWindow (\n             mUITSWM,\n             mClientImageHandle,\n             EFI_HII_OUT_FLAG_CLIP |\n             EFI_HII_OUT_FLAG_CLIP_CLEAN_X | EFI_HII_OUT_FLAG_CLIP_CLEAN_Y |\n             EFI_HII_IGNORE_LINE_BREAK | EFI_HII_DIRECT_TO_SCREEN,\n             this->m_pButton->pButtonText,\n             StringInfo,\n             &pBltBuffer,\n             this->m_pButton->ButtonTextBounds.Left,\n             this->m_pButton->ButtonTextBounds.Top,\n             NULL,\n             NULL,\n             NULL\n             );\n\n  AuroraCanvasDiagnosticResult (\"BUTTON TEXT\", DiagnosticCallStatus);\n  AuroraCanvasDiagnosticStage (215);\n\nExit:\n  AuroraCanvasDiagnosticStage (216);\n\n  if (NULL != StringInfo) {\n    FreePool (StringInfo);\n  }\n\n  if (NULL != pBltBuffer) {\n    FreePool (pBltBuffer);\n  }\n\n  if (EFI_ERROR (Status)) {\n    AuroraCanvasDiagnosticResult (\"RENDER SETUP\", Status);\n  }\n  AuroraCanvasDiagnosticStage (217);\n  return Status;\n}\n"
BUTTON_DRAW_ORIGINAL = "static\nOBJECT_STATE\nDraw (\n  IN    Button           *this,\n  IN    BOOLEAN          DrawHighlight,\n  IN    SWM_INPUT_STATE  *pInputState,\n  OUT   VOID             **pSelectionContext\n  )\n{\n  SWM_RECT  *pRect   = &this->m_pButton->ButtonBounds;\n  VOID      *Context = NULL;\n\n  // If there is no input state, simply draw the button then return.\n  //\n  if ((NULL == pInputState) || (this->m_pButton->State == GRAYED)) {\n    RenderButton (\n      this,\n      DrawHighlight\n      );\n\n    goto Exit;\n  }\n\n  // If there is user keyboard input, handle it here.  For buttons, we only recognize\n  // <ENTER> and <SPACE> as valid keys.  Both select the button.\n  //\n  if (SWM_INPUT_TYPE_KEY == pInputState->InputType) {\n    EFI_KEY_DATA  *pKey = &pInputState->State.KeyState;\n\n    if ((CHAR_CARRIAGE_RETURN == pKey->Key.UnicodeChar) || (L' ' == pKey->Key.UnicodeChar)) {\n      this->m_pButton->State = SELECT;\n      Context                = this->m_pSelectionContext;\n    } else {\n      // Unrecognized keyboard input - simply exit.\n      //\n      goto Exit;\n    }\n\n    // Draw the button.\n    //\n    RenderButton (\n      this,\n      DrawHighlight\n      );\n\n    // We're done, exit.\n    //\n    goto Exit;\n  }\n\n  // If there is touch input, check whether the pointer location falls within the button's bounding box.\n  //\n  if ((SWM_INPUT_TYPE_TOUCH == pInputState->InputType) &&\n      (pInputState->State.TouchState.CurrentX >= pRect->Left) && (pInputState->State.TouchState.CurrentX <= pRect->Right) &&\n      (pInputState->State.TouchState.CurrentY >= pRect->Top) && (pInputState->State.TouchState.CurrentY <= pRect->Bottom))\n  {\n    this->m_pButton->State = HOVER;\n    if (pInputState->State.TouchState.ActiveButtons & 0x1) {\n      this->m_ButtonDown = TRUE;\n    } else {\n      if (this->m_ButtonDown == TRUE) {\n        this->m_pButton->State = SELECT;\n        Context                = this->m_pSelectionContext;\n      }\n    }\n  } else {\n    if (KEYDEFAULT != this->m_pButton->State) {\n      this->m_pButton->State = NORMAL;\n    }\n\n    this->m_ButtonDown = FALSE;\n  }\n\n  // Draw the button.\n  //\n  RenderButton (\n    this,\n    DrawHighlight\n    );\n\nExit:\n\n  if (NULL != pSelectionContext) {\n    *pSelectionContext = Context;\n  }\n\n  return (this->m_pButton->State);\n}\n"
